try:
    print('>>> x = 3')
    print('>>> y = {}')
    print('>>> x >> y')
    x = 3
    y = {}
    print(x >> y)
except Exception as e:
    print(type(e), ':', e)
print()
##################################################
try:
    print('>>> x = 3')
    print('>>> y = {"a": 1, "c": 2.3456, "d": "another"}')
    print('>>> x >> y')
    x = 3
    y = {"a": 1, "c": 2.3456, "d": "another"}
    print(x >> y)
except Exception as e:
    print(type(e), ':', e)
print()
